byte_repository_len equ $ - byte_repository

newline_byte:
    db 10

section .text
global _start

; --- GlyphAssemblyStrategy: the bytes are already contiguous, so assembling
;     them is just handing the pointer/length straight through ---
; in:  rdi = pointer, rsi = length
; out: rax = pointer, rdx = length
glyph_assembly_strategy_assemble:
    mov rax, rdi
    mov rdx, rsi
    ret

; --- DocumentAssemblyEngine: renders the repository through the strategy ---
document_assembly_engine_render:
    mov rdi, byte_repository
    mov rsi, byte_repository_len
    call glyph_assembly_strategy_assemble
    ret

; --- ConsoleOutputSink: writes a payload (rax = pointer, rdx = length) to
;     stdout, followed by a trailing newline ---
console_output_sink_write_line:
    mov rsi, rax
    mov rdi, 1              ; fd = stdout
    mov rax, 1              ; sys_write
    syscall
    mov rsi, newline_byte
    mov rdx, 1
    mov rdi, 1
    mov rax, 1
    syscall
    ret

; --- DocumentCompilerFacade: orchestrates render + write ---
document_compiler_facade_execute:
    call document_assembly_engine_render
    call console_output_sink_write_line
    ret

_start:
    call document_compiler_facade_execute
    mov rax, 60              ; sys_exit
    xor rdi, rdi
    syscall
